static fractal_result point(const fractal_formula_vtable*f,const fractal_numeric_vtable*n,const fractal_formula_parameters*p,double x,double y,uint32_t budget,const fractal_cancellation*cancel,fractal_point_result_compact*out){fractal_complex_state state;uint32_t i;if(!f||!n||!out||budget==0||f->state_size()>sizeof(state)||f->validate_parameters(p)!=FRACTAL_OK)return FRACTAL_ERROR_INVALID_ARGUMENT;memset(out,0,sizeof(*out));out->classification=FRACTAL_CLASS_UNRESOLVED;if(f->initialize_state(n,p,x,y,&state)!=FRACTAL_OK)return FRACTAL_ERROR_INVALID_SPEC;for(i=1;i<=budget;i++){fractal_point_class c;if(cancel&&cancel->requested){out->classification=FRACTAL_CLASS_CANCELLED;return FRACTAL_ERROR_CANCELLED;}if(f->step(n,&state)!=FRACTAL_OK){out->classification=FRACTAL_CLASS_FAILED;return FRACTAL_OK;}out->steps=i;if(f->classify(n,&state,&c)!=FRACTAL_OK)return FRACTAL_ERROR_INVALID_SPEC;if(c==FRACTAL_CLASS_ESCAPED){out->classification=(uint8_t)c;return FRACTAL_OK;}}return FRACTAL_OK;}
const fractal_compute_vtable fractal_compute_conventional={&d_compute,FRACTAL_CAP_POINT_SCALAR,FRACTAL_CAP_SCALAR_ARITHMETIC,point};
